def legal_add_query(queries, answers, identity, operation, units, choice):
    clean = []
    for unit in units:
        if type(unit) is int and unit not in clean:
            clean.append(unit)
    clean = sorted(clean)
    if not clean:
        return
    query = {'id': identity, 'operation': operation, 'unit_ids': clean}
    answer = {'id': identity, 'choice': choice, 'evidence_unit_ids': clean}
    for old in queries:
        if old.get('id') == identity:
            if old != query:
                raise ValueError('Conflicting clause-group query')
            return
    queries.append(query)
    answers.append(answer)

def legal_add_fragment(fragments, term, supports, query_ids):
    clean_supports = []
    clean_queries = []
    for unit in supports:
        if type(unit) is int and unit not in clean_supports:
            clean_supports.append(unit)
    for identity in query_ids:
        if isinstance(identity, str) and identity and identity not in clean_queries:
            clean_queries.append(identity)
    if term is None or not clean_supports or not clean_queries:
        return
    row = {'term': term, 'support_ids': sorted(clean_supports), 'query_ids': clean_queries}
    for old in fragments:
        if old == row:
            return
    fragments.append(row)

def legal_union(values):
    clean = []
    seen = set()
    for value in values:
        key = repr(value)
        if value is not None and key not in seen:
            seen.add(key)
            clean.append(value)
    if not clean:
        return None
    out = clean[0]
    i = 1
    while i < len(clean):
        out = ['participant_union', out, clean[i]]
        i += 1
    return out

def legal_roles(text, spans, supports):
    low = text.lower()
    starts = []
    for token in ('disclose', 'divulge', 'reveal', 'share', 'restrict access', 'provide access'):
        position = low.find(token)
        if position >= 0:
            starts.append(position)
    tail = low[min(starts):] if starts else low
    receiver = ['receiving_party']
    parts = []
    extra = []
    if any(token in tail for token in ('any other person', 'any other party', 'third party', 'third-party', 'third parties', 'anyone')):
        parts.append(['third_parties'])
    alias = ''
    if 'representative' in tail:
        for span in spans:
            if not isinstance(span, dict) or type(span.get('id')) is not int or not isinstance(span.get('text'), str):
                continue
            candidate = span.get('text')
            candidate_low = candidate.lower()
            if 'representative' in candidate_low and (' means ' in candidate_low or 'collectively' in candidate_low) and any(word in candidate_low for word in ('employee', 'director', 'officer', 'agent', 'advisor', 'adviser', 'consultant', 'accountant', 'attorney', 'lender')):
                alias = candidate_low
                if span.get('id') not in supports and span.get('id') not in extra:
                    extra.append(span.get('id'))
                break
    role_text = tail + ' ' + alias
    controlled = any(token in role_text for token in ('affiliate', 'subsidiar', 'member of such party\'s group', 'member of its group', 'owned or controlled', 'common control', 'controlled legal entity'))
    own_owner = receiver
    controlled_owner = ['controlled_entities_of', receiver]
    role_map = [('employees_of', ('employee', 'members of its staff', 'personnel')), ('officers_of', ('officer', 'official')), ('directors_of', ('director',)), ('agents_of', ('agent',)), ('consultants_of', ('consultant',)), ('independent_contractors_of', ('contractor',)), ('professional_advisors_of', ('professional adviser', 'professional advisor', 'advisor', 'adviser')), ('legal_advisors_of', ('legal adviser', 'legal advisor', 'attorney', 'legal counsel')), ('financial_advisors_of', ('financial adviser', 'financial advisor')), ('accountants_of', ('accountant',)), ('lenders_of', ('lender', 'finance provider'))]
    actor_only = (' by our agents' in tail or ' by its representatives' in tail or ' by their representatives' in tail) and not any(token in tail for token in (' to our ', ' to its ', ' to their ', ' except ', ' only to ', ' reveal the information to'))
    if not actor_only:
        for constructor, words in role_map:
            if any(word in role_text for word in words):
                parts.append([constructor, own_owner])
                if controlled:
                    parts.append([constructor, controlled_owner])
    if 'representative' in tail and not alias and not actor_only:
        parts.append(['representatives_of', receiver])
    return [legal_union(parts), extra]

def legal_material(text):
    low = text.lower()
    info = ['confidential_information']
    copies = ['copies_of', info]
    derivatives = any(token in low for token in ('notes', 'abstracts', 'extracts', 'analyses', 'analysis', 'summaries', 'compilations', 'derivative', 'work product'))
    has_copies = any(token in low for token in ('all copies', 'copies thereof', 'including copies', 'together with all copies', 'and copies', 'copy thereof'))
    if derivatives and has_copies:
        return ['information_bundle', ['information_bundle', info, copies], ['derivative_materials_of', info]]
    if derivatives:
        return ['information_bundle', info, ['derivative_materials_of', info]]
    if has_copies:
        return ['information_bundle', info, copies]
    return info

def legal_trigger(text):
    low = text.lower()
    values = []
    if any(token in low for token in ('upon request', 'on request', 'upon demand', 'written demand', 'if requested', 'at any time upon request')):
        values.append(['request_by', ['disclosing_party']])
    if any(token in low for token in ('termination or expiration of the agreement', 'termination or expiration of this agreement', 'termination of this agreement', 'expiration of this agreement', 'upon termination of this agreement', 'upon termination or expiration of the agreement')):
        values.append(['agreement_termination'])
    if any(token in low for token in ('termination of service', 'termination of employment')):
        values.append(['service_termination'])
    if any(token in low for token in ('termination of the business relationship', 'termination/expiration of the business relation', 'termination of the relationship', 'project termination', 'expiration or other termination of the project')):
        values.append(['relationship_termination'])
    if any(token in low for token in ('completion of the purpose', 'purpose is completed', 'completion of the project')):
        values.append(['purpose_completion'])
    if any(token in low for token in ('business relationship is not entered into', 'if a business relationship is not entered into')):
        values.append(['relationship_nonformation_deadline'])
    if not values:
        return None
    out = values[0]
    i = 1
    while i < len(values):
        out = ['trigger_alternative', out, values[i]]
        i += 1
    return out

def legal_retention_signal(text):
    low = text.lower()
    if 'continue to apply to such retained' in low or ('continue to be bound' in low and 'return' in low):
        return False
    return any(token in low for token in ('may retain', 'entitled to retain', 'may maintain a single copy', 'legal department may maintain', 'will not be required to delete', 'not required to delete', 'shall not be destroyed until', 'will be held by us and kept confidential', 'may keep a copy', 'retain in the files of its legal counsel'))

def legal_neural(inputs, queries, answers, fragments, unresolved):
    old = retained_apply(inputs, {})
    semantic = inputs.get('semantic_answers', [])
    groups = {}
    modes = {}
    for answer in semantic:
        if not isinstance(answer, dict):
            continue
        identity = answer.get('id', '')
        if not isinstance(identity, str) or '|unit|' not in identity:
            continue
        anchor = identity.rsplit('|unit|', 1)[1]
        if answer.get('operation') == 'disclosure_modality':
            modes[anchor] = answer.get('choice')
    for row in old.get('fragments', []):
        if not isinstance(row, dict):
            continue
        anchor = ''
        for identity in row.get('query_ids', []):
            if isinstance(identity, str) and '|unit|' in identity:
                anchor = identity.rsplit('|unit|', 1)[1]
                break
        if not anchor:
            continue
        group = groups.setdefault(anchor, {'supports': [], 'rows': []})
        for unit in row.get('support_ids', []):
            if type(unit) is int and unit not in group['supports']:
                group['supports'].append(unit)
        group['rows'].append(row)
    for anchor, group in groups.items():
        mode = modes.get(anchor)
        choice = 'source_other'
        if mode in ('operative_class_permission', 'prohibition_with_embedded_class_permission'):
            choice = 'source_permission'
        elif mode == 'operative_general_prohibition':
            choice = 'source_prohibition'
        qid = 'program:neural-clause:' + anchor
        legal_add_query(queries, answers, qid, 'source_clause_kind', group['supports'], choice)
        for row in group['rows']:
            legal_add_fragment(fragments, row.get('term'), row.get('support_ids', []), [qid] + row.get('query_ids', []))
    for item in old.get('unresolved', []):
        if isinstance(item, str) and item not in unresolved:
            unresolved.append(item)
